/* =====================================================================================================
   MANUAL SQL UPGRADE SCRIPT
   Migration: 202609171120001_AzureCostTagColumns
   =====================================================================================================
   For operators / DBAs who upgrade the Analytics database schema BY HAND instead of running the
   installer (which applies EF migrations automatically). It performs the same schema changes as the
   migration and then stamps __MigrationHistory so EF (DatabaseUpgrader / MigrateDatabaseToLatestVersion)
   and the web app Health page recognise it as applied.

   RUN ORDER
     The manual scripts form a strict prerequisite chain - run them in migration-id order. This one's
     predecessor is 202609171030001_CopilotAdoptionDigest. If that migration is not already stamped in
     __MigrationHistory this script applies its columns but deliberately does NOT stamp, and tells you so.

   WHAT IT DOES
     Gives the Azure cost import somewhere to record the tag it grouped the Cost Management query by.

     Microsoft bills Copilot Cowork, Work IQ API and Copilot Studio through a SINGLE shared Copilot
     Credits meter - "Pay As You Go Copilot Credit", under the "Microsoft Copilot Studio" service - and
     publishes no separate Azure line item per experience. The only thing that tells them apart is a tag
     on the usage record (observed as serviceName / policyName). Note that tag is injected by the billing
     pipeline: it is NOT an ARM tag, and does not appear on the resource in the Azure portal's resource
     view. Without these columns, "how much of this was Cowork?" cannot be answered from stored data.

     New columns
       * azure_cost_daily.tag_key    - nvarchar(256) NULL. The tag name grouped by, e.g. serviceName.
       * azure_cost_daily.tag_value  - nvarchar(512) NULL. That tag's value for the row, e.g. Cowork.

     nvarchar rather than varchar because tag values are tenant-controlled text and may be non-Latin.

   ACTION REQUIRED AFTER RUNNING: NONE, BUT NOTHING CHANGES ON ITS OWN.
     The columns stay NULL until an operator opts in by setting the AzureCostGroupBy application setting
     to include a tag, e.g. "ResourceId;TagKey:serviceName". Cost Management allows only TWO group-by
     clauses, so a tag grouping costs one of them - normally traded against Meter. Leaving the setting
     alone preserves today's behaviour exactly.

   NO BACKFILL, AND NONE IS POSSIBLE.
     Existing rows keep NULL. The value cannot be recovered from stored data because the Cost Management
     query API only returns tags when the query GROUPS BY a tag key, so rows already imported were
     fetched without it. Once a tag grouping is configured the importer's next run repopulates the
     trailing window (the Azure write replaces a scope and window rather than appending); rows older than
     that window stay NULL permanently.

   RUNTIME
     Instant, at any table size, on every SQL Server edition.

     Both statements are ALTER TABLE ... ADD of a NULLable column with NO DEFAULT, which SQL Server
     applies as a metadata-only change - it does not rewrite the table and does not scan it. There is no
     index build and no foreign key, so nothing here holds a schema-modification lock for any meaningful
     duration. Safe to run with the importer running; no maintenance window is required.

   SAFETY
     * Idempotent: every step is guarded and re-running is a no-op.
     * The stamp is guarded and is reached on the "already applied" path as well, so running this against
       an already-up-to-date database still reconciles __MigrationHistory rather than leaving the
       migration pending.
     * The stamp refuses only if the COLUMNS are missing - i.e. the schema work did not complete. It
       never inspects row data. (A data-state guard has broken a customer upgrade before: concurrency
       always beats it, and EF's own installer path does not apply one.)
   ===================================================================================================== */

SET NOCOUNT ON;
GO

/* =====================================================================================================
   1. azure_cost_daily.tag_key
   ===================================================================================================== */
IF OBJECT_ID(N'dbo.azure_cost_daily', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.azure_cost_daily', N'tag_key') IS NULL
BEGIN
    ALTER TABLE [dbo].[azure_cost_daily] ADD [tag_key] [nvarchar](256) NULL;
    RAISERROR('AzureCostTagColumns: added azure_cost_daily.tag_key.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('AzureCostTagColumns: azure_cost_daily.tag_key already present (or table missing), skipping.', 0, 1) WITH NOWAIT;
GO

/* =====================================================================================================
   2. azure_cost_daily.tag_value
   ===================================================================================================== */
IF OBJECT_ID(N'dbo.azure_cost_daily', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.azure_cost_daily', N'tag_value') IS NULL
BEGIN
    ALTER TABLE [dbo].[azure_cost_daily] ADD [tag_value] [nvarchar](512) NULL;
    RAISERROR('AzureCostTagColumns: added azure_cost_daily.tag_value.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('AzureCostTagColumns: azure_cost_daily.tag_value already present (or table missing), skipping.', 0, 1) WITH NOWAIT;
GO

/* =====================================================================================================
   3. Record the migration so EF (DatabaseUpgrader / MigrateDatabaseToLatestVersion) and the web app
      Health page treat it as applied.

      This migration DOES change the EF entity model, so the predecessor's Model blob cannot be reused:
      EF reads the LAST history row's Model as the source for automatic migrations, and a stale blob
      would make it try to re-add these columns. The model snapshot below is the gzipped EDMX from
      202609171120001_AzureCostTagColumns.resx, emitted in chunks so no single line is
      unreasonably long. Guarded, so re-running is safe.
   ===================================================================================================== */
IF NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = N'202609171120001_AzureCostTagColumns')
BEGIN
    /* ---------------------------------------------------------------------------------------------
       Refuse to stamp unless the schema work above actually completed.

       This script is split into GO batches, and by default sqlcmd/SSMS CONTINUE to the next batch after
       a statement fails - a severity-16 error aborts its own batch, not the script. Without this check
       an interrupted or partially failed run would fall through to the stamp and record the migration
       as applied when it is not, which is worse than the original error: EF would then believe the
       schema is at this version and skip the migration forever.

       This checks SCHEMA ONLY - do the columns exist. It deliberately does not look at row data.
       --------------------------------------------------------------------------------------------- */
    DECLARE @missing nvarchar(max) = N'';

    IF COL_LENGTH(N'dbo.azure_cost_daily', N'tag_key') IS NULL
        SET @missing += N'azure_cost_daily.tag_key; ';
    IF COL_LENGTH(N'dbo.azure_cost_daily', N'tag_value') IS NULL
        SET @missing += N'azure_cost_daily.tag_value; ';

    IF @missing <> N''
    BEGIN
        DECLARE @incomplete nvarchar(max) =
            N'AzureCostTagColumns: NOT stamped - the schema changes did not complete. Missing: '
            + @missing
            + N'Re-run this script (it is guarded and safe to repeat) and check the earlier output for the '
            + N'failure. The migration is deliberately left unstamped so the upgrade can be retried.';
        RAISERROR(@incomplete, 16, 1) WITH NOWAIT;
    END
    ELSE
    IF EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = N'202609171030001_CopilotAdoptionDigest')
    BEGIN
        DECLARE @model varbinary(max);
        SET @model = ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;
        SET @model = @model + ;

        INSERT INTO dbo.__MigrationHistory (MigrationId, ContextKey, Model, ProductVersion)
        SELECT N'202609171120001_AzureCostTagColumns', ContextKey, @model, ProductVersion
        FROM dbo.__MigrationHistory
        WHERE MigrationId = N'202609171030001_CopilotAdoptionDigest';
        RAISERROR('AzureCostTagColumns: recorded in __MigrationHistory.', 0, 1) WITH NOWAIT;
    END
    ELSE
    BEGIN
        DECLARE @noPrev nvarchar(max) =
            N'AzureCostTagColumns: NOT stamped - the predecessor migration 202609171030001_CopilotAdoptionDigest '
            + N'is not recorded in __MigrationHistory. Run the manual scripts in migration-id order, then '
            + N're-run this one. The columns above have been applied and re-running is safe.';
        RAISERROR(@noPrev, 16, 1) WITH NOWAIT;
    END
END
ELSE
    RAISERROR('AzureCostTagColumns: already recorded in __MigrationHistory, nothing to do.', 0, 1) WITH NOWAIT;
GO
